ESPECIES = [{'nome': 'Jararaca (Bothrops jararaca)', 'cientifico': 'Bothrops jararaca', 'regiao': 'Brasil (principalmente Sul, Sudeste e parte do Centro-Oeste)', 'veneno': 'Dor e inchaço local, sangramentos e alterações da coagulação; casos graves podem causar lesão dos tecidos e dos rins.'}, {'nome': 'Cascavel (Crotalus durissus)', 'cientifico': 'Crotalus durissus', 'regiao': 'Brasil', 'veneno': 'Fraqueza, pálpebras caídas, visão turva ou dupla e lesão muscular; a urina pode ficar escura.'}, {'nome': 'Surucucu-pico-de-jaca (Lachesis muta)', 'cientifico': 'Lachesis muta', 'regiao': 'Regiões de floresta amazônica e Mata Atlântica', 'veneno': 'Dor e inchaço, sangramentos e manifestações como náuseas, vômitos, diarreia e queda de pressão.'}, {'nome': 'Coral-verdadeira (Micrurus corallinus)', 'cientifico': 'Micrurus corallinus', 'regiao': 'Brasil, sobretudo áreas do Sudeste e Sul', 'veneno': 'Pode provocar visão dupla, pálpebras caídas, dificuldade para falar ou engolir, fraqueza e paralisia respiratória.'}, {'nome': 'Jararaca-da-seca (Bothrops erythromelas)', 'cientifico': 'Bothrops erythromelas', 'regiao': 'Caatinga do Nordeste brasileiro', 'veneno': 'Dor e inchaço local, sangramentos e alterações da coagulação; a gravidade varia.'}, {'nome': 'Cotiara (Bothrops cotiara)', 'cientifico': 'Bothrops cotiara', 'regiao': 'Sul do Brasil, em áreas de Mata Atlântica e campos de altitude', 'veneno': 'Dor e inchaço, equimoses e possíveis hemorragias e alterações da coagulação.'}, {'nome': 'Jararacussu (Bothrops jararacussu)', 'cientifico': 'Bothrops jararacussu', 'regiao': 'Partes do Brasil, especialmente áreas de Mata Atlântica', 'veneno': 'Dor e edema importantes, sangramentos e possibilidade de dano tecidual; casos graves podem ser severos.'}, {'nome': 'Urutu-cruzeiro (Bothrops alternatus)', 'cientifico': 'Bothrops alternatus', 'regiao': 'Sul e partes do Sudeste e Centro-Oeste do Brasil, além de países vizinhos', 'veneno': 'Dor, inchaço progressivo, equimoses, bolhas em alguns casos e alterações da coagulação/necrose.'}, {'nome': 'Mamba-negra (Dendroaspis polylepis)', 'cientifico': 'Dendroaspis polylepis', 'regiao': 'África subsaariana', 'veneno': 'Pode causar formigamento, tontura, fraqueza, paralisia e insuficiência respiratória de progressão rápida.'}, {'nome': 'Taipan-do-interior (Oxyuranus microlepidotus)', 'cientifico': 'Oxyuranus microlepidotus', 'regiao': 'Interior árido da Austrália', 'veneno': 'Pode causar efeitos neurotóxicos, alterações da coagulação, lesão muscular e dano renal.'}, {'nome': 'Naja-indiana (Naja naja)', 'cientifico': 'Naja naja', 'regiao': 'Sul da Ásia, incluindo Índia e regiões próximas', 'veneno': 'Dor e inchaço podem ocorrer; o veneno pode causar fraqueza, alterações neurológicas e paralisia respiratória.'}, {'nome': 'Cobra-rei (Ophiophagus hannah)', 'cientifico': 'Ophiophagus hannah', 'regiao': 'Sul e Sudeste Asiático', 'veneno': 'Pode provocar dor e edema, tontura, sonolência, fraqueza e paralisia, incluindo comprometimento respiratório.'}, {'nome': 'Víbora-de-Russell (Daboia russelii)', 'cientifico': 'Daboia russelii', 'regiao': 'Sul da Ásia', 'veneno': 'Dor e inchaço, sangramentos, alterações graves da coagulação, queda de pressão e possível lesão renal.'}, {'nome': 'Víbora-da-morte (Acanthophis antarcticus)', 'cientifico': 'Acanthophis antarcticus', 'regiao': 'Austrália', 'veneno': 'Pode causar fraqueza progressiva, pálpebras caídas, paralisia e dificuldade respiratória.'}, {'nome': 'Serpente-marinha-de-Belcher (Hydrophis belcheri)', 'cientifico': 'Hydrophis belcheri', 'regiao': 'Oceano Índico e águas do Sudeste Asiático', 'veneno': 'Envenenamento por serpentes marinhas pode causar dor ou rigidez muscular, fraqueza, urina escura e paralisia; nem toda mordida injeta veneno.'}, {'nome': 'Cobra-marrom-oriental (Pseudonaja textilis)', 'cientifico': 'Pseudonaja textilis', 'regiao': 'Austrália e sul da Nova Guiné', 'veneno': 'Pode causar alterações da coagulação e sangramentos, colapso cardiovascular e efeitos neurotóxicos.'}, {'nome': 'Mamba-verde-oriental (Dendroaspis angusticeps)', 'cientifico': 'Dendroaspis angusticeps', 'regiao': 'Costa oriental da África', 'veneno': 'Pode causar dor ou inchaço, tontura, náusea, fraqueza, alterações neurológicas e dificuldade respiratória.'}, {'nome': 'Víbora-das-pirâmides (Echis carinatus)', 'cientifico': 'Echis carinatus', 'regiao': 'Partes do Oriente Médio e Sul da Ásia', 'veneno': 'Dor e inchaço, alterações graves da coagulação, sangramentos e possível dano renal.'}, {'nome': 'Mocassim-de-cabeça-de-cobre (copperhead) (Agkistrodon contortrix)', 'cientifico': 'Agkistrodon contortrix', 'regiao': 'Leste e centro dos Estados Unidos', 'veneno': 'Dor, vermelhidão e inchaço local; podem ocorrer bolhas e danos locais. A gravidade varia.'}, {'nome': 'Cascavel-diamante-do-leste (Crotalus adamanteus)', 'cientifico': 'Crotalus adamanteus', 'regiao': 'Sudeste dos Estados Unidos', 'veneno': 'Dor e edema, sangramento local, alterações da coagulação e queda de pressão em acidentes graves.'}]

